// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address actor) public {
        // any admissible actor (not the zero address, not the contract itself which was
        // granted TIMELOCK_ADMIN_ROLE at construction); role is fully fuzzed
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // only the account itself may renounce its role
        vm.prank(actor);
        c.renounceRole(role, actor);

        // General rule: renouncing a role can never leave the account holding it.
        // Reference: renounce revokes (or is a no-op if never held) -> hasRole == false.
        // Mutant: renounce grants the role -> hasRole == true for a fresh role/actor.
        assertTrue(!c.hasRole(role, actor));
    }
}
